      /* --- Model routing (Models page) --- */
      mrSectionTitle: "Model routing advice",
      mrSectionBody: "ForkLight compares historical evidence across provider/model pairs. The result is advice for Main — Main still chooses. No automatic selection, no settings mutation, and no billable request runs.",
      mrWhatIsDecided: "What is being decided",
      mrWhatIsDecidedBody: "Give similar work the same short name. ForkLight then looks only at finished work with that name and compares the selected models using independently checked results.",
      mrPolicyAdvancedTitle: "Advanced: change how evidence is weighed",
      mrPolicyTitle: "Evidence preferences",
      mrPolicyMinSamples: "Minimum relevant samples",
      mrPolicyMinSamplesHint: "Fewer than this → no recommendation; evidence is reported but is too thin to compare. Must be ≥ 1.",
      mrPolicyUncertainty: "Uncertainty threshold",
      mrPolicyUncertaintyHint: "Score gap between top two must be larger than this fraction. 0 means any gap produces a recommendation; 1 means never recommend. Must be 0.0–1.0.",
      mrPolicyCompetition: "Competition on uncertainty",
      mrPolicyCompetitionHint: "When evidence is insufficient or scores are too close, suggest a competition instead of picking a winner.",
      mrPolicyWeightsTitle: "Factor weights",
      mrPolicyAcceptedDelivery: "Accepted delivery",
      mrPolicyAcceptedDeliveryHint: "How much Main-backed accepted final deliveries count. Higher values prefer models whose work Main actually accepts, repairs, or integrates. Machine success without Main or delivery evidence is unavailable, not a success. Participates only when every candidate has enough comparable final-delivery outcomes.",
      mrAcceptedDeliverySummary: "Accepted final delivery asks whether Main accepted the result, verified a Main repair, or applied Integration. Independent machine checks alone are not final delivery.",
      mrAcceptedDeliveryFact: "Main accepted {accepted} of {sample} comparable final-delivery outcomes ({rate}%).",
      mrAcceptedDeliveryNoComparable: "No comparable Main or delivery decisions yet for this candidate.",
      mrAcceptedDeliveryUnavailable: "{count} finished Tasks still lack a current Main or delivery decision and are not scored here.",
      mrAcceptedDeliveryNotMachine: "Machine success without Main accept, verified repair, or applied Integration is unavailable — never treated as accepted delivery. This factor never disables a model; Main remains free to override the advice.",
      mrPolicyVerifiedBehavior: "Verified behavior",
      mrPolicyVerifiedBehaviorHint: "How much independently-checked correct behavior counts. Higher values prefer models whose results pass verification.",
      mrPolicyModelQualityFailure: "Model-quality failure penalty",
      mrPolicyModelQualityFailureHint: "How much verification failures reduce a model's score. Higher values punish models that fail independent checks.",
      mrPolicyCorrectionChurn: "Correction churn penalty",
      mrPolicyCorrectionChurnHint: "How much repeated correction reduces the score. Higher values favour models whose result needs less Main repair.",
      mrPolicyFirstPassSuccess: "First-pass verified success",
      mrPolicyFirstPassSuccessHint: "How much to prefer a Worker that passes independent behavior checks on its first Attempt. This is not the same as eventual accepted delivery or total correction effort. Missing verification and external failures (credentials, Provider, budget, workspace, interruption) are excluded rather than counted as first-pass failures. 0 = visible but does not affect ranking.",
      mrPolicyOfficialCost: "Official cost weight",
      mrPolicyOfficialCostHint: "How much official Provider pricing evidence influences the choice. 0 = visible but does not affect ranking. Only works when all candidates have comparable official-cost evidence in the same currency.",
      mrPolicyDuration: "Duration weight",
      mrPolicyDurationHint: "How much runtime duration evidence influences the choice. 0 = visible but does not affect ranking. Only works when all candidates have complete duration samples.",
      mrPolicyBudgetReliability: "Reached review before hitting the limit",
      mrPolicyBudgetReliabilityHint: "How much to prefer a model that reaches a reviewable result before its USD or Token limit. 0 means it does not affect ranking. Runs are compared only when the same limits were actually enforced. An uncapped success is not proof that it can finish under a limit. This is not model quality and not a Provider bill.",
      mrWeightZeroNote: "This factor is recorded as evidence but set to zero weight — it does not affect the recommendation.",
      mrCostUnavailable: "Official cost is unavailable for one or more candidates (different currencies, missing quotes, or incomplete coverage). It does not affect the recommendation even at non-zero weight.",
      mrDurationUnavailable: "Duration is not available for one or more candidates (incomplete coverage). It does not affect the recommendation even at non-zero weight.",
      mrBudgetReliabilityUnavailable: "This cannot be compared yet because the runs do not share enough trustworthy evidence under the same enforced USD or Token limits.",
      mrBudgetReliabilitySummary: "This asks a narrow question: under the same enforced USD or Token limits, how often did the run reach a reviewable result before the limit stopped it? It is not task success, model quality, a cost estimate, or a Provider bill.",
      mrBudgetReliabilityEnvelopeMissing: "There are not enough runs with an enforced USD or Token limit. Successful runs with no limit do not count as proof here.",
      mrBudgetReliabilityEnvelopeMixedCandidate: "This candidate used different limits across its comparable runs, so those runs are not mixed into one rate.",
      mrBudgetReliabilityEnvelopeMismatch: "The candidates were run with different limits, so comparing them directly would be unfair.",
      mrBudgetReliabilityCoverageIncomplete: "There are not enough comparable runs under the same limits yet.",
